TEST='\n#include "mock.h"\n#include <assert.h>\n#include <stdio.h>\nuint32_t mock_ms;int mock_deinit,mock_send_result;const uint8_t *mock_inflight;\n#include "now_radio.c"\n#include "master_guard.h"\nstatic void body(uint8_t *b,unsigned node,unsigned kind){memset(b,0,80);b[0]=\'W\';b[1]=\'N\';b[2]=1;b[3]=kind;b[4]=(uint8_t)node;b[24]=4;b[25]=1;uint32_t c=now_crc32(b,60);memcpy(b+60,&c,4);}\nstatic void receive(uint8_t *b,unsigned i){esp_now_recv_info_t n={peers[i].mac,local};recv_cb(&n,b,80);}\nint main(void){\n assert(now_radio_init());uint8_t b[80],out[64];uint32_t at;\n body(b,1,4);for(unsigned i=0;i<1000;i++)receive(b,0);\n body(b,2,3);receive(b,1);assert(now_radio_receive_frame(out,&at)&&out[4]==2);\n assert(uxQueueMessagesWaiting(peers[0].wave_rx)==8);assert(atomic_load(&wave_drop)==992);\n puts("PASS waveform flood cannot consume other peer control queue");\n xQueueReset(peers[0].wave_rx);body(b,2,3);receive(b,0);assert(!now_radio_receive_frame(out,&at));\n puts("PASS source MAC/node binding rejects cross-node packet");\n body(b,1,2);for(unsigned i=0;i<8;i++)receive(b,0);b[25]=0;uint32_t c=now_crc32(b,60);memcpy(b+60,&c,4);receive(b,0);assert(now_radio_receive_frame(out,&at)&&out[25]==0);\n puts("PASS reserved STOP slot preempts full motion queue");\n xQueueReset(peers[0].rx);body(b,1,3);receive(b,0);mock_ms=101;assert(!now_radio_receive_frame(out,&at));\n puts("PASS delayed control status expires without renewing state");\n body(b,1,2);now_radio_send(b);body(b,2,5);b[26]=1;b[28]=1;now_radio_send(b);now_radio_service();unsigned first=packet[4];const uint8_t *stable=mock_inflight;\n uint8_t held[80];memcpy(held,stable,80);now_radio_service();assert(!memcmp(held,stable,80));send_cb(NULL,ESP_NOW_SEND_FAIL);now_radio_service();assert(packet[4]!=first);send_cb(NULL,ESP_NOW_SEND_SUCCESS);\n puts("PASS round robin sends both peers; failed MAC send never replays movement");\n body(b,1,2);now_radio_send(b);body(b,2,5);b[26]=1;b[28]=1;now_radio_send(b);body(b,1,2);b[25]=0;now_radio_send(b);assert(uxQueueMessagesWaiting(peers[1].tx)==1);now_radio_service();assert(packet[4]==1&&packet[25]==0);\n puts("PASS one-peer STOP flush does not erase other-peer command");\n mock_ms+=251;now_radio_service();assert(recovering&&!ready&&mock_deinit==1);mock_ms+=1001;now_radio_service();assert(ready&&!recovering&&!sending);\n puts("PASS callback timeout deinitializes MAC before buffer reuse and purges stale queues");\n master_guard_t a={0},d={0};now_request_t q={.kind=5,.node=2,.boot=8,.epoch=1,.session=9,.seq=1};q.command[0]=0xaa;q.command[2]=1;q.command[4]=8;\n master_guard_query(&d,0);master_guard_status(&d,8,1,0);assert(master_guard_command(&d,&q,0));d.unlocked=true;q.command[4]=1;q.seq=2;assert(master_guard_command(&d,&q,10));assert(!master_guard_command(&d,&q,20));\n master_guard_query(&a,500);master_guard_status(&a,7,1,500);assert(master_guard_expired(&d,true,611));assert(!master_guard_expired(&a,true,611));master_guard_loss(&d);master_guard_query(&d,612);master_guard_status(&d,8,1,612);assert(!master_guard_command(&d,&q,612));\n puts("PASS independent guards reject duplicate/retired session; one lane timeout does not expire other");\n return 0;\n}\n'
